/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PARTY   (kind: hub, origin: data_7.js.parent)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PARTY_HK
   hashdiff    : SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSPITAL_ID))) as HUB_PARTY_HK
        , RELATION as RELATIONSHIP_TO_INSURED
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(HOSPITAL_ID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RELATIONSHIP_TO_INSURED end) as RELATIONSHIP_TO_INSURED,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when RELATIONSHIP_TO_INSURED is not null
                     then md5(upper(coalesce(cast(RELATIONSHIP_TO_INSURED as varchar), '')))
                end as SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS_HASHDIFF is not null
